def standard():
    vals = set()
    for path in itertools.product("AB", repeat=4):
        p, q = Fraction(1), Fraction(0)
        seqp = [(p, q)]
        for ch in path:
            p, q = (p, q - 2) if ch == "A" else (3 * p, 3 * q)
            seqp.append((p, q))
        p4, q4 = seqp[3]
        if p4 == 1:
            continue
        a1 = -q4 / (p4 - 1)
        p5, q5 = seqp[4]
        vals.add(p5 * a1 + q5)
    return max(vals)

def unique():
